-- 0071: Toronto Midtown basketball becomes a Winter 2027 landing page.
--
-- Owner request (Oct 30, 2026): the page at /toronto-midtown/basketball shows
-- only the ALL CAN Basketball League (Youth League), with a Register button
-- that links out to the Playbook registration page, no interest form, and
-- landing-page copy built from the Winter 2027 program summary. Skills is
-- archived (not deleted) until it has a season of its own.
--
-- The page's blocks start with a hero, which puts the location-sport template
-- in landing mode (hero, program record, then the rest). Photo spots are image
-- and gallery blocks with no file yet: the caption is the brief for the shot.

alter table public.site_programs add column if not exists register_url text;
comment on column public.site_programs.register_url is 'External registration page (e.g. Playbook). Register button while status = open and no Play program is linked.';

update public.site_programs set
  status = 'open',
  status_label = 'Registration open · Winter 2027',
  description = 'Evaluation session first, then balanced teams and a game every Saturday. All skill levels welcome.',
  facts = '[["Ages", "9 to 17 · 13U (ages 9 to 13) and 17U (ages 13 to 17)"], ["Format", "Evaluation session first, then balanced teams and a game every Saturday."], ["Day and time", "Saturdays · 13U 3:30 to 5:00pm · 17U 5:00 to 6:30pm"], ["Season", "8 Saturdays, January 23 to March 13, 2027 · Semifinals March 6 · Championship Day March 13"], ["Venue", "De La Salle College, John Hunt Student Life Centre · 131 Farnham Avenue, Toronto, ON M4V 1H7"], ["Price", "$350 + HST"], ["Included", "Reversible ALL CAN jersey and shorts · welcome package (backpack, socks, stickers) · playoffs · Championship Day and prizes · photo day"], ["Coach", "Tye Appleton, Head Coach and Convenor"], ["Registration", "Open now on Playbook"]]'::jsonb,
  register_url = 'https://athleteinstitute.playbookapi.com/programs/more_info/season/59214/',
  updated_at = now()
where brand_key = 'all-can' and slug = 'toronto-midtown-basketball-league';

update public.site_programs set status = 'archived', updated_at = now()
where brand_key = 'all-can' and slug = 'toronto-midtown-basketball-skills';

update public.site_locations set
  status = 'open',
  launch_label = 'Winter 2027 · Registration open',
  calendar = '[["Registration", "Open now"], ["Evaluation session", "[TBC]"], ["First Saturday", "January 23, 2027"], ["Semifinals", "March 6, 2027"], ["Championship Day", "March 13, 2027"]]'::jsonb,
  updated_at = now()
where brand_key = 'all-can' and slug = 'toronto-midtown';

update public.site_pages set
  blocks_published = '[{"id": "hero", "type": "hero", "props": {"style": "photo", "imageUrl": "", "imageAlt": "", "credit": "[TBC]", "kicker": "Toronto Midtown · Youth League · Winter 2027", "headingLines": ["ALL CAN Basketball League."], "heading": "ALL CAN Basketball League.", "subheading": "8 Saturdays at De La Salle College. An evaluation first, then balanced teams and a game every week. Every skill level welcome.", "ctaLabel": "Register now", "ctaHref": "https://athleteinstitute.playbookapi.com/programs/more_info/season/59214/", "ctaSecondaryLabel": "See the details", "ctaSecondaryHref": "#toronto-midtown-basketball-league", "height": "short"}}, {"id": "stats", "type": "stats_band", "props": {"items": [{"value": "8", "label": "Saturdays"}, {"value": "9 to 17", "label": "Ages · two divisions"}, {"value": "$350", "label": "Per player · plus HST"}, {"value": "Jan 23", "label": "First game · 2027"}]}}, {"id": "who", "type": "rich_text", "props": {"label": "Who it''s for", "heading": "Every kid plays.", "width": "narrow", "html": "<p>Whether your child is picking up a ball for the first time or has played for years, there''s a spot for them in the ALL CAN League.</p><p>Players attend an evaluation session first. From there we build balanced teams, play every week and learn the game in a fun, welcoming, professionally run environment. All skill levels are welcome.</p>"}}, {"id": "photo-game", "type": "image", "props": {"imageUrl": "", "alt": "", "caption": "Photo spot: game action at the John Hunt Student Life Centre. Landscape, players in ALL CAN reversibles, families courtside.", "credit": "", "size": "wide", "href": ""}}, {"id": "divisions", "type": "fact_block", "props": {"label": "Divisions", "heading": "Two divisions.<br>One Saturday.", "facts": [["13U", "Ages 9 to 13 · Saturdays, 3:30 to 5:00pm"], ["17U", "Ages 13 to 17 · Saturdays, 5:00 to 6:30pm"], ["Where", "De La Salle College, John Hunt Student Life Centre · 131 Farnham Avenue, Toronto, ON M4V 1H7"], ["Coach", "Tye Appleton, Head Coach and Convenor"]], "note": "Not sure which division fits? Use Ask ALL CAN at the top of the page, or email info@athleteinstitute.ca.", "programSlug": "", "locationSlug": ""}}, {"id": "included", "type": "rich_text", "props": {"label": "Included", "heading": "More than games.", "width": "narrow", "html": "<p>Every registration includes:</p><ul><li>Reversible ALL CAN jersey and shorts</li><li>Welcome package: backpack, socks and a sticker pack</li><li>An evaluation session and balanced teams</li><li>8-week season with playoffs</li><li>Championship Day with prizes</li><li>Photo day</li></ul>"}}, {"id": "dates", "type": "fact_block", "props": {"label": "Season dates", "heading": "Eight Saturdays.", "facts": [["Week 1", "Saturday, January 23"], ["Week 2", "Saturday, January 30"], ["Week 3", "Saturday, February 6"], ["Week 4", "Saturday, February 13"], ["Week 5", "Saturday, February 20"], ["Week 6", "Saturday, February 27"], ["Week 7", "Saturday, March 6 · Semifinals"], ["Week 8", "Saturday, March 13 · Championship Day"]], "note": "All dates 2027. Weather cancellations are emailed to every family.", "programSlug": "", "locationSlug": ""}}, {"id": "gallery", "type": "gallery_grid", "props": {"images": [{"url": "", "alt": "Photo spot: a skills drill, coach with players"}, {"url": "", "alt": "Photo spot: a huddle or high-fives after a game"}, {"url": "", "alt": "Photo spot: the welcome package, jersey, shorts and backpack laid out"}], "programId": ""}}, {"id": "coach", "type": "columns", "props": {"columns": [[{"id": "coach-photo", "type": "image", "props": {"imageUrl": "", "alt": "", "caption": "Photo spot: Tye Appleton, portrait, 4 by 5.", "credit": "", "size": "narrow", "href": ""}}], [{"id": "coach-text", "type": "rich_text", "props": {"label": "Your coach", "heading": "Coached by Tye Appleton.", "width": "narrow", "html": "<p>Tye is the Head Coach and Convenor for the Toronto Midtown league: on the floor every Saturday, running the evaluation, building the teams and leading the coaching staff.</p><p>[TBC] Two lines on Tye''s coaching background and what families can expect from him.</p>"}}]]}}, {"id": "faq", "type": "faq", "props": {"label": "Before you register", "openFirst": true, "items": [{"q": "How do I register?", "a": "Register now takes you to our registration partner, Playbook. Create a family account, add your player and choose ALL CAN Basketball League, Winter 2027. You will get a confirmation email.", "note": ""}, {"q": "My child has never played. Is that okay?", "a": "Yes. Everyone starts with an evaluation session, and we build balanced teams from there. Beginners and experienced players both have a place.", "note": ""}, {"q": "What should we bring?", "a": "Indoor shoes and a water bottle. The reversible jersey and shorts are issued at the start of the season.", "note": ""}, {"q": "How are teams formed?", "a": "Players are placed by division and the evaluation session and, where possible, friend requests.", "note": ""}, {"q": "What about missed weeks and weather?", "a": "Missed sessions aren''t refunded. Weather cancellations are emailed to every family.", "note": ""}, {"q": "Refunds and cancellations", "a": "Requests go through the contact page, never social messages.", "note": ""}, {"q": "Is there financial help?", "a": "Yes. Financial assistance is available for every ALL CAN program. See the financial assistance page before you register.", "note": ""}]}}, {"id": "cta", "type": "cta_band", "props": {"heading": "Ready for Winter 2027?", "body": "Registration is open now. 8 Saturdays, January 23 to March 13. $350 plus HST.", "buttons": [{"label": "Register now", "href": "https://athleteinstitute.playbookapi.com/programs/more_info/season/59214/", "style": "red"}, {"label": "Financial assistance", "href": "/financial-assistance", "style": "line"}], "background": "ink"}}]'::jsonb,
